# HVM2 runtime settings for B200 GPU
def configure_hvm_runtime() -> RuntimeConfig:
  RuntimeConfig {
    device: "cuda",
    num_threads: 10000,  # Maximum parallelism on B200
    memory_pool_size: 8_000_000_000,  # 8GB per GPU
    optimization_level: 3,
    use_tensor_cores: true,
    shared_memory_size: 164_000  # 164KB shared memory per SM
  }

# Automatic work distribution
def distribute_work(image_size: (i32, i32), num_gpus: i32) -> WorkDistribution:
  (height, width) = image_size
  pixels_per_gpu = (height * width) / num_gpus

  WorkDistribution {
    chunks: range(0, num_gpus).map(λgpu_id:
      start_pixel = gpu_id * pixels_per_gpu
      end_pixel = (gpu_id + 1) * pixels_per_gpu
      GPUChunk { gpu_id, start_pixel, end_pixel }
    )
  }
