    (target_w: i64) 
    (weights: coupling_weights) : tensor3d =
  let scale_h = f32.i64 target_h / f32.i64 h
  let scale_w = f32.i64 target_w / f32.i64 w
  -- Learned upsampling via transposed convolution
  let upsampled = transposed_conv2d low_res weights.upsample_kernel scale_h scale_w
  -- Refinement with coupling flow
  let refined = map3 (\plane y x ->
                  let local_context = extract_context upsampled y x 3
                  let flow_correction = coupling_flow local_context weights.coupling_net
                  in plane + flow_correction
                ) upsampled (iota target_h) (iota target_w)
  in refined
```

**Tensor Core Integration:**
```futhark
-- File: src/flow_generator/tensor_core_ops.fut
-- Utilize wmma intrinsics for matrix multiplication
entry matmul_16x16x16_tc [n][m][k] (a: [n][m]f16) (b: [m][k]f16) : [n][k]f32 =
  let tile_size = 16
  -- Tile matrices for Tensor Core processing
  let a_tiles = tile_matrix a tile_size tile_size
  let b_tiles = tile_matrix b tile_size tile_size
  -- Parallel Tensor Core execution
  let result_tiles = map2 (\a_tile_row b_tile_col ->
                      map2 (\a_tile b_tile ->
                        wmma_multiply a_tile b_tile
                      ) a_tile_row b_tile_col
                    ) a_tiles (transpose b_tiles)
  in untile_matrix result_tiles

-- Fused operations for memory efficiency
entry fused_conv_relu_tc [n][h][w][c_in][c_out] 
    (input: [n][h][w][c_in]f16) 
    (kernel: [c_out][c_in]f16)[2]
    (bias: [c_out]f16) : [n][h][w][c_out]f32 =
  map (\batch ->
    map2 (\y x ->
      map (\k_out ->
        let conv_sum = reduce (+) 0f16 (
          flatten (map2 (\k_in kernel_slice ->
            map2 (\ky kx ->
              let iy = y + ky - 1
              let ix = x + kx - 1
              in if iy >= 0 && iy < h && ix >= 0 && ix < w
                 then input[batch,iy,ix,k_in] * kernel_slice[ky,kx]
                 else 0f16
            ) (iota 3) (iota 3)
          ) (iota c_in) kernel[k_out])
        )
        let biased = conv_sum + bias[k_out]
        in f32.max 0f32 (f32.f16 biased)  -- ReLU activation
      ) (iota c_out)
    ) (iota h) (iota w)
  ) input
```

