            split="train"
        )

        # DiffusionDB (2M prompt-image pairs)
        diffusiondb = load_dataset(
            "poloclub/diffusiondb",
            "large_random_1k",
            streaming=True
        )

        # SAM (11M images with segmentation masks)
        sam = load_dataset(
            "nielsr/saim-dataset",
            streaming=True,
            split="train"
        )

        # Combine datasets with weights
        combined = self.weighted_interleave([
            (laion, 0.4),
            (journeydb, 0.3),
            (diffusiondb, 0.2),
            (sam, 0.1)
        ])

        return combined

    def preprocessing_pipeline(self, example):
        """Futhark preprocessing on GPU"""
        image = example["image"]
        prompt = example["caption"]

        # Call Futhark preprocessing kernel
        processed_image = futhark_preprocess_image(
            image,
            target_size=(1024, 1024),
            normalize=True,
            augment=True
        )

        # Tokenize prompt
        tokens = tokenize_prompt(prompt, max_length=77)

        # Generate segmentation if SAM dataset
        if "segmentation" in example:
            seg_mask = example["segmentation"]
        else:
            seg_mask = None

        return {
            "image": processed_image,
            "tokens": tokens,
            "segmentation": seg_mask
        }

    def create_dataloader(self):
        dataset = self.load_all_datasets()
        dataset = dataset.map(
            self.preprocessing_pipeline,
            batched=True,
            batch_size=self.batch_size
        )

        return DataLoader(
            dataset,
            batch_size=self.batch_size,
            num_workers=self.num_workers,
            pin_memory=True,
            persistent_workers=True
        )
```

**Futhark Preprocessing:**
```futhark
-- File: src/data/preprocessing.fut
entry preprocess_image [h][w][c] 
    (image: [h][w][c]u8) 
    (target_h: i64) 
    (target_w: i64) : [target_h][target_w][c]f32 =
  -- Resize using bilinear interpolation
  let resized = resize_bilinear image target_h target_w

  -- Normalize to [-1, 1]
  let normalized = map (map (map (\x -> f32.u8 x / 127.5 - 1.0))) resized

  -- Random augmentation
  let augmented = if rand_bool() 
                  then horizontal_flip normalized 
                  else normalized

  let augmented = if rand_bool() 
                  then random_brightness augmented (rand_range -0.2 0.2)
                  else augmented

  let augmented = if rand_bool() 
                  then random_contrast augmented (rand_range 0.8 1.2)
                  else augmented

  in augmented

entry preprocess_batch [n][h][w][c]
    (images: [n][h][w][c]u8)
    (target_h: i64)
    (target_w: i64) : [n][target_h][target_w][c]f32 =
  map (\img -> preprocess_image img target_h target_w) images

-- Efficient batched resize using parallel scan
entry resize_bilinear [h][w][c] 
    (image: [h][w][c]u8) 
    (new_h: i64) 
    (new_w: i64) : [new_h][new_w][c]f32 =
  let scale_h = f32.i64 h / f32.i64 new_h
  let scale_w = f32.i64 w / f32.i64 new_w

  tabulate_2d new_h new_w (\y x ->
    let src_y = f32.i64 y * scale_h
    let src_x = f32.i64 x * scale_w

    let y0 = i64.f32 (floor src_y)
    let y1 = min (y0 + 1) (h - 1)
    let x0 = i64.f32 (floor src_x)
    let x1 = min (x0 + 1) (w - 1)

    let dy = src_y - f32.i64 y0
    let dx = src_x - f32.i64 x0

    map (\channel ->
      let v00 = f32.u8 image[y0,x0,channel]
      let v01 = f32.u8 image[y0,x1,channel]
      let v10 = f32.u8 image[y1,x0,channel]
      let v11 = f32.u8 image[y1,x1,channel]

      let v0 = v00 * (1.0 - dx) + v01 * dx
      let v1 = v10 * (1.0 - dx) + v11 * dx

      v0 * (1.0 - dy) + v1 * dy
    ) (iota c)
  )
